public Object convertToCharacter(Class type, Object value) throws Exception {
    // Check if the input value is already a Character
    if (value instanceof Character) {
        return value;
    }

    // Check if the input value is a string
    if (value instanceof String) {
        // Try to convert the string to a Character
        try {
            return Character.valueOf(((String) value).charAt(0));
        } catch (StringIndexOutOfBoundsException e) {
            // If the string is empty, throw an exception
            throw new Exception("The input string is empty");
        }
    }

