        int correctedDesiredCapacity = (desiredCapacity / 100) * 110; // Correct for desiredCapacity >= 1000
        int start = Math.max(correctedDesiredCapacity, 1000); // Start from the corrected desiredCapacity or 1000
        for (int i = start; i <= correctedDesiredCapacity; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    } else {
        for (int i = desiredCapacity; i <= 1000; i++) {
