private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSum = new ArrayList<>();
    long sumOfElements = 0;

    // Iterate over the bounds list and compute the suffix sum
    for (int i = 0; i < bounds.size(); i++) {
        int x = bounds.get(i);
        sumOfElements += x;
        suffixSum.add(sumOfElements);
    }

    // Return the computed suffix sum and the sum of all elements
    return new Pair<>(suffixSum, sumOfElements);
}

