public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the row index is valid
    if (row < 0 || row >= table.getRowCount()) {
        throw new IndexOutOfBoundsException("Row index " + row + " is not valid");
    }

    // Select the row in the JTable
    table.setRowSelectionInterval(row, row);

    // Calculate the coordinates of the row in the JTable
    Rectangle rect = table.getCellRect(row, 0, true);

    // Scroll the JScrollPane if necessary
    if (rect.y < pane.getViewport().getViewPosition().y ||
            rect.y + rect.height > pane.getViewport().getViewPosition().y + pane.getViewport().getExtentSize().height) {
        pane.getViewport().setViewPosition(new Point(pane.getViewport().getViewPosition().x, rect.y));
    }

    // Repaint the JTable to show the newly selected row
    table.repaint();
}

